contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val, uint _val2) public payable {
        // Pre-initialization SetMinSum calls are allowed and must set MinSum.
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        uint minAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;
        require(minAfterFirst == _val);

        c.SetMinSum(_val2); if (__ESBMC_reverted()) return;
        uint minAfterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(minAfterSecond == _val2);
    }
}

