pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 _val, uint256 _val2) internal {
        try c.SetMinSum(_val) {} catch { return; }
        uint256 minAfterFirst;
        try c.MinSum() returns (uint256 __r) { minAfterFirst = __r; } catch { return; }
        _val = minAfterFirst;
        try c.SetMinSum(_val2) {} catch { return; }
        uint256 minAfterSecond;
        try c.MinSum() returns (uint256 __r) { minAfterSecond = __r; } catch { return; }
        assertTrue(minAfterSecond == _val2);
    }

    function testFuzz_run(uint256 _val, uint256 _val2) public {
        _run(_val, _val2);
    }

    receive() external payable {}
}
